export interface PricingPlan {
  pricingPlanId: number;
  planCode: string;
  planName: string;
  tagline?: string;
  priceMonthly: number;
  priceYearly?: number;
  currency: string;
  featuresList: string;
  ctaLabel: string;
  ctaUrl: string;
  isFeatured: boolean;
  isActive: boolean;
  sortOrder: number;
  created_At: string;
  updated_at?: string;
}

export interface PricingPlanListResponse {
  pricingPlans: PricingPlan[];
}

// GET ALL — POST /all_pricingPlans
export async function getAllPricingPlans(): Promise<PricingPlan[]> {
  const res = await fetch(BASE_URL + "/all_pricingPlans", {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ pricingPlans: [{}] }), // No companyId, empty object as per backend_artifacts' docs for all_pricingPlans.txt
  });
  if (!res.ok) throw new Error(await res.text());
  const data: PricingPlanListResponse = await res.json();
  return data.pricingPlans ?? [];
}

// CREATE — action: 1
export async function createPricingPlan(payload: Omit<PricingPlan, "pricingPlanId" | "created_At" | "updated_at">): Promise<PricingPlan> {
  const res = await fetch(BASE_URL + "/pricingPlans", {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ pricingPlans: [{ action: 1, ...payload }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  return await res.json();
}

// UPDATE — action: 2
export async function updatePricingPlan(id: number, payload: Partial<Omit<PricingPlan, "created_At">_>): Promise<PricingPlan> {
  const res = await fetch(BASE_URL + "/pricingPlans", {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ pricingPlans: [{ action: 2, pricingPlanId: id, ...payload }] }),
  });
  if (!res.ok) throw new Error(await res.text());
  return await res.json();
}

